  async function triggerAutoAnalysis(){try{const response=await fetch("/api/insights",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({automatic:true})});if(response.ok){const result=await response.json();setRuns(result.runs??[]);setComments(result.comments??[]);flash("Entry saved and the latest AI review is ready.")}else{const result=await response.json();flash(result.error??"Entry saved; automatic AI review could not run.")}}catch{flash("Entry saved; automatic AI review could not run.")}}
  async function saveAiSettings(event:FormEvent<HTMLFormElement>){event.preventDefault();const raw=Object.fromEntries(new FormData(event.currentTarget).entries());setBusy(true);try{const response=await fetch("/api/settings",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({...raw,consent:raw.consent==="on",autoAnalyze:raw.autoAnalyze==="on"})});const result=await response.json();if(!response.ok)throw new Error(result.error??"Could not save settings.");await loadSettings();setApiKey("");flash("AI settings saved securely.")}catch(error){flash(error instanceof Error?error.message:"Could not save settings.")}finally{setBusy(false)}}
